def apply(inputs, premises):
    descriptions = inputs["asset_descriptions"]
    values = inputs["asset_values"]
    asset_types = inputs["asset_types"]
    debtor_count = int(inputs["debtor_count"])
    answer = {}
    for i in range(len(descriptions)):
        claims = []
        asset_value = float(values[i])
        for j in range(len(premises["rule_citations"])):
            applicable = premises["rule_protected_types"][j] == "any" or premises["rule_protected_types"][j] == asset_types[i]
            if applicable:
                if inputs["output_family"] == "EC":
                    claims = claims + [premises["rule_citations"][j]]
                else:
                    cap = float(premises["rule_base_caps"][j])
                    if premises["rule_per_debtor"][j]:
                        cap = cap * debtor_count
                    if cap < 0:
                        claim_value = asset_value
                    else:
                        claim_value = min(asset_value, cap)
                    claims = claims + [{"citation": premises["rule_citations"][j], "claim_value": claim_value}]
        answer[descriptions[i]] = claims
    return {"answer": answer}

def apply(inputs, premises):
    year = int(inputs["tax_year"])
    answer = year >= int(premises["first_zero_year"]) and year <= int(premises["last_zero_year"])
    return {"answer": answer}

def apply(inputs, premises):
    actual_entitlement = bool(premises["dependent_exemption_authorized"]) and bool(inputs["is_dependent_for_tax_year"])
    if bool(inputs["claim_asserts_entitlement"]) == actual_entitlement:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}

def apply(inputs, premises):
    if premises["actual_knowledge_only"]:
        knowledge_mode = "actual"
        answer = "Actual knowledge"
    else:
        knowledge_mode = "constructive"
        answer = "Constructive knowledge"
    return {"answer": answer, "knowledge_mode": knowledge_mode}

def apply(inputs, premises):
    if inputs["knowledge_mode"] == "actual":
        answer = bool(inputs["specified_person_satisfied"]) and bool(inputs["actual_known"])
    else:
        answer = bool(inputs["specified_person_satisfied"]) and (bool(inputs["actual_known"]) or bool(inputs["inquiry_would_reveal"]))
    return {"answer": answer}

def apply(inputs, premises):
    if premises["pandemic_carveout_present"]:
        answer = "Yes"
    else:
        answer = "No"
    return {"answer": answer}
